import os, json

files = {
  "Dockerfile": "# Use Official Python Base Image\nFROM python:3.10-slim\n\n# Set Working Directory\nWORKDIR /app\n\n# Install System Dependencies\nRUN apt-get update && apt-get install -y --no-install-recommends \\\n    build-essential \\\n    curl \\\n    && rm -rf /var/lib/apt/lists/*\n\n# Copy Project Requirements & Files\nCOPY . /app\n\n# Install Python Libraries from requirements.txt\nRUN pip install --no-cache-dir --upgrade pip\nRUN pip install --no-cache-dir -r requirements.txt\n\n# Expose Web Port 8000 and Backend API Port 5000\nEXPOSE 8000 5000\n\n# Command to Run Both Server & Web App via Python\nCMD [\"sh\", \"-c\", \"python server.py & python -m http.server 8000\"]\n",
  "docker-compose.yml": "version: '3.8'\n\nservices:\n  zenith-algo-terminal:\n    build: .\n    container_name: zenith_algo_pro\n    restart: always\n    ports:\n      - \"8000:8000\"\n      - \"5000:5000\"\n    environment:\n      - PORT=8000\n      - PYTHONUNBUFFERED=1\n",
  "requirements.txt": "upstox-python-sdk>=2.0.0\nbreeze-connect>=1.0.0\npandas>=2.0.0\nnumpy>=1.24.0\nflask>=3.0.0\nflask-cors>=4.0.0\nrequests>=2.31.0\ngunicorn>=21.2.0\nyfinance>=0.2.0\n",
  "config.json": "{\n  \"app_name\": \"ZenithAlgo Pro\",\n  \"version\": \"2.0.0\",\n  \"default_broker\": \"Upstox API v2\",\n  \"supported_brokers\": [\"Upstox API v2\", \"ICICI Direct Breeze API\"],\n  \"risk_settings\": {\n    \"default_capital_inr\": 500000,\n    \"max_risk_per_trade_pct\": 1.5,\n    \"max_daily_loss_limit_inr\": 10000,\n    \"enforce_stoploss\": true\n  },\n  \"default_symbols\": [\"NIFTY\", \"BANKNIFTY\", \"RELIANCE\", \"TCS\", \"TATAMOTORS\", \"HDFCBANK\"],\n  \"server\": {\n    \"web_port\": 8000,\n    \"api_port\": 5000,\n    \"gcp_region\": \"asia-south1 (Mumbai)\"\n  }\n}\n",
  "server.py": "\"\"\"\n=============================================================================\nZenithAlgo Pro - Backend API Server (Upstox & ICICI Breeze Bridge)\n=============================================================================\nRuns locally on http://localhost:5000 to bridge web UI button clicks to live broker APIs.\n\"\"\"\n\nfrom flask import Flask, request, jsonify\nfrom flask_cors import CORS\nimport sys\nimport json\nimport yfinance as yf\nfrom upstox_algo_bot import UpstoxBot\nfrom icici_breeze_algo_bot import ICICIBreezeBot\n\napp = Flask(__name__)\nCORS(app)\n\n# Global Store for Broker Credentials and State\nbroker_config = {\n    'upstox': {'instance': None, 'status': 'Disconnected'},\n    'icici': {'instance': None, 'status': 'Disconnected'}\n}\n\n# Dad's Safety Guard State\ncurrent_daily_loss = 0.0\n\n# Load config\nwith open('config.json', 'r') as f:\n    config_data = json.load(f)\nMAX_DAILY_LOSS = config_data.get('risk_settings', {}).get('max_daily_loss_limit_inr', 10000)\n\n@app.route('/')\ndef home():\n    return jsonify({\"status\": \"ZenithAlgo Backend API Gateway Running\", \"version\": \"2.0\"})\n\n@app.route('/api/connect_broker', methods=['POST'])\ndef connect_broker():\n    data = request.json\n    broker = data.get('broker')\n    \n    if broker == 'Upstox':\n        access_token = data.get('access_token', '')\n        try:\n            bot = UpstoxBot(access_token)\n            broker_config['upstox']['instance'] = bot\n            broker_config['upstox']['status'] = 'Connected'\n            return jsonify({\"status\": \"success\", \"message\": \"Upstox API v2 Connected Successfully!\"})\n        except Exception as e:\n            return jsonify({\"status\": \"error\", \"message\": str(e)}), 400\n            \n    elif broker == 'ICICI Direct Breeze':\n        app_key = data.get('app_key', '')\n        secret_key = data.get('secret_key', '')\n        session_token = data.get('session_token', '')\n        try:\n            bot = ICICIBreezeBot(app_key, secret_key, session_token)\n            broker_config['icici']['instance'] = bot\n            broker_config['icici']['status'] = 'Connected'\n            return jsonify({\"status\": \"success\", \"message\": \"ICICI Direct Breeze API Connected Successfully!\"})\n        except Exception as e:\n            return jsonify({\"status\": \"error\", \"message\": str(e)}), 400\n    \n    return jsonify({\"status\": \"error\", \"message\": \"Invalid Broker\"}), 400\n\n@app.route('/api/execute_order', methods=['POST'])\ndef execute_order():\n    global current_daily_loss\n    data = request.json\n    symbol = data.get('symbol', 'NIFTY')\n    action = data.get('action', 'BUY')\n    qty = data.get('quantity', 50)\n    price = data.get('price', 0.0)\n    broker = data.get('broker', 'Upstox API v2')\n\n    print(f\"[LIVE EXECUTION] {action} {qty} Qty of {symbol} at \u20b9{price} via {broker}\")\n\n    # Dad's Safety Guard Check\n    if current_daily_loss >= MAX_DAILY_LOSS:\n        print(\"[SAFETY GUARD TRIGGERED] Max daily loss exceeded. Order BLOCKED.\")\n        return jsonify({\n            \"status\": \"error\",\n            \"message\": f\"Dad's Safety Guard: Daily loss limit of \u20b9{MAX_DAILY_LOSS} exceeded! Trade blocked.\"\n        }), 403\n\n    order_id = None\n    \n    try:\n        if 'Upstox' in broker:\n            bot = broker_config['upstox']['instance']\n            if not bot:\n                return jsonify({\"status\": \"error\", \"message\": \"Upstox not connected!\"}), 400\n            order_id = bot.place_order(f'NSE_EQ|{symbol}', qty, price, action)\n            \n        elif 'ICICI' in broker:\n            bot = broker_config['icici']['instance']\n            if not bot:\n                return jsonify({\"status\": \"error\", \"message\": \"ICICI not connected!\"}), 400\n            order_id = bot.place_order(symbol, qty, price, action)\n        else:\n            return jsonify({\"status\": \"error\", \"message\": \"Unknown broker\"}), 400\n            \n        if order_id:\n            return jsonify({\n                \"status\": \"success\",\n                \"order_id\": order_id,\n                \"message\": f\"Successfully placed {action} order for {qty} shares of {symbol} on {broker}!\"\n            })\n        else:\n            return jsonify({\"status\": \"error\", \"message\": \"Broker API failed to place order.\"}), 500\n            \n    except Exception as e:\n        return jsonify({\"status\": \"error\", \"message\": str(e)}), 500\n\n@app.route('/api/market_data', methods=['GET'])\ndef market_data():\n    symbol = request.args.get('symbol', 'NIFTY')\n    # Map app symbols to yfinance symbols\n    yf_symbol_map = {\n        'NIFTY': '^NSEI',\n        'BANKNIFTY': '^NSEBANK',\n        'RELIANCE': 'RELIANCE.NS',\n        'TCS': 'TCS.NS',\n        'TATAMOTORS': 'TATAMOTORS.NS',\n        'HDFCBANK': 'HDFCBANK.NS'\n    }\n    yf_sym = yf_symbol_map.get(symbol, '^NSEI')\n    \n    try:\n        data = yf.download(tickers=yf_sym, period='5d', interval='5m')\n        if data.empty:\n            return jsonify({\"status\": \"error\", \"message\": \"No data found.\"}), 404\n        \n        # Take the last 60 candles\n        data = data.tail(60)\n        \n        candles = []\n        for index, row in data.iterrows():\n            candles.append({\n                \"time\": index.isoformat(),\n                \"open\": float(row['Open'].iloc[0]) if hasattr(row['Open'], 'iloc') else float(row['Open']),\n                \"high\": float(row['High'].iloc[0]) if hasattr(row['High'], 'iloc') else float(row['High']),\n                \"low\": float(row['Low'].iloc[0]) if hasattr(row['Low'], 'iloc') else float(row['Low']),\n                \"close\": float(row['Close'].iloc[0]) if hasattr(row['Close'], 'iloc') else float(row['Close']),\n                \"volume\": int(row['Volume'].iloc[0]) if hasattr(row['Volume'], 'iloc') else int(row['Volume'])\n            })\n        \n        return jsonify({\"status\": \"success\", \"candles\": candles})\n    except Exception as e:\n        return jsonify({\"status\": \"error\", \"message\": str(e)}), 500\n\nif __name__ == '__main__':\n    print(\"==================================================\")\n    print(\"   ZenithAlgo Pro Backend API Gateway Started     \")\n    print(\"   Listening on http://localhost:5000             \")\n    print(\"==================================================\")\n    app.run(host='0.0.0.0', port=5000, debug=False)\n",
  "upstox_algo_bot.py": "\"\"\"\n=============================================================================\nZenithAlgo Pro - Official Upstox API v2 Python Automated Execution Script\n=============================================================================\nRequirements:\n    pip install upstox-python-sdk pandas numpy\n\nSetup Instructions:\n    1. Create a developer account at https://developer.upstox.com/\n    2. Obtain API Key and API Secret.\n    3. Generate Daily Access Token via OAuth login.\n\"\"\"\n\nimport upstox_client\nfrom upstox_client.rest import ApiException\nimport time\n\nclass UpstoxBot:\n    def __init__(self, access_token):\n        self.configuration = upstox_client.Configuration()\n        self.configuration.access_token = access_token\n        self.api_client = upstox_client.ApiClient(self.configuration)\n        \n        self.order_api = upstox_client.OrderApi(self.api_client)\n        self.portfolio_api = upstox_client.PortfolioApi(self.api_client)\n\n    def place_order(self, symbol, quantity, limit_price, transaction_type=\"BUY\"):\n        \"\"\"\n        Places an Intraday order on Upstox API v2.\n        \"\"\"\n        body = upstox_client.PlaceOrderRequest(\n            quantity=quantity,\n            product='I',              # 'I' = Intraday (MIS), 'D' = Delivery (CNC)\n            validity='DAY',\n            price=float(limit_price),\n            tag=f'ZENITH_ALGO_{transaction_type}',\n            instrument_token=symbol, # e.g. 'NSE_EQ|INE002A01018'\n            order_type='LIMIT',\n            transaction_type=transaction_type.upper(),\n            disclosed_quantity=0,\n            trigger_price=0.0,\n            is_amo=False\n        )\n        try:\n            response = self.order_api.place_order(body, api_version='2.0')\n            print(f\"[SUCCESS] {transaction_type} Order Executed! Order ID: {response.data.order_id}\")\n            return response.data.order_id\n        except ApiException as e:\n            print(f\"[ERROR] Failed to place Upstox order: {e}\")\n            return None\n\n    def get_positions(self):\n        \"\"\"\n        Fetches active positions to enforce Dad's Safety Guard Rules.\n        \"\"\"\n        try:\n            response = self.portfolio_api.get_positions(api_version='2.0')\n            print(\"[INFO] Active Positions Fetched Successfully.\")\n            return response.data\n        except ApiException as e:\n            print(f\"[ERROR] Could not fetch positions: {e}\")\n            return None\n\nif __name__ == \"__main__\":\n    print(\"==================================================\")\n    print(\"      ZenithAlgo - Upstox API Bot Running         \")\n    print(\"==================================================\")\n    \n    # Demonstration Call\n    # bot = UpstoxBot(\"YOUR_DAILY_UPSTOX_ACCESS_TOKEN\")\n    # print(\"Simulating Upstox Strategy Trigger...\")\n    # bot.place_order('NSE_EQ|INE002A01018', 50, 2980.0, \"BUY\")\n",
  "icici_breeze_algo_bot.py": "\"\"\"\n=============================================================================\nZenithAlgo Pro - Official ICICI Direct Breeze API Python Execution Script\n=============================================================================\nRequirements:\n    pip install breeze-connect pandas numpy\n\nSetup Instructions:\n    1. Register on ICICI Direct Breeze API Portal: https://api.icicidirect.com/\n    2. Obtain App Key and Secret Key.\n    3. Generate Daily Session Token after customer login.\n\"\"\"\n\nfrom breeze_connect import BreezeConnect\nimport time\n\nclass ICICIBreezeBot:\n    def __init__(self, app_key, secret_key, session_token):\n        self.app_key = app_key\n        self.secret_key = secret_key\n        self.session_token = session_token\n        \n        self.breeze = BreezeConnect(api_key=self.app_key)\n        self.authenticate()\n\n    def authenticate(self):\n        \"\"\"\n        Establishes daily session with ICICI Direct Breeze API.\n        \"\"\"\n        try:\n            self.breeze.generate_session(api_secret=self.secret_key, session_token=self.session_token)\n            print(\"[SUCCESS] Connected to ICICI Direct Breeze API!\")\n        except Exception as e:\n            print(f\"[ERROR] Authentication failed: {e}\")\n\n    def place_order(self, stock_code, qty, price, transaction_type=\"BUY\", stoploss_price=0):\n        \"\"\"\n        Places an Intraday / Margin order on ICICI Direct.\n        \"\"\"\n        try:\n            response = self.breeze.place_order(\n                stock_code=stock_code,       # e.g., 'NIFTY' or 'RELIANCE'\n                exchange_code=\"NSE\",\n                product=\"margin\",            # 'margin' for intraday, 'cash' for delivery\n                action=transaction_type.lower(),\n                order_type=\"limit\",\n                stoploss=str(stoploss_price),\n                quantity=str(qty),\n                price=str(price),\n                validity=\"day\"\n            )\n            print(f\"[SUCCESS] Order Placed! Response: {response}\")\n            return response\n        except Exception as e:\n            print(f\"[ERROR] Failed to place Breeze order: {e}\")\n            return None\n\nif __name__ == \"__main__\":\n    print(\"==================================================\")\n    print(\"   ZenithAlgo - ICICI Breeze API Bot Running     \")\n    print(\"==================================================\")\n    \n    # Example Execution (Uncomment after filling daily credentials)\n    # bot = ICICIBreezeBot(\"YOUR_APP_KEY\", \"YOUR_SECRET_KEY\", \"YOUR_SESSION_TOKEN\")\n    # bot.place_order(\"RELIANCE\", 50, 2980.0, \"BUY\", 2930.0)\n",
  "index.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>ZenithAlgo Pro - Algorithmic Trading & Indicator Studio</title>\n    <!-- Google Fonts -->\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n    <!-- Font Awesome Icons -->\n    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n    <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n    <!-- Top Navigation Bar -->\n    <header class=\"navbar\">\n        <div class=\"brand\">\n            <div class=\"logo-icon\">\n                <i class=\"fa-solid fa-chart-line-up\"></i>\n            </div>\n            <div class=\"brand-text\">\n                <h1>ZENITH<span>ALGO</span> PRO</h1>\n                <p>Institutional Grade Trading Terminal for Indian Markets</p>\n            </div>\n        </div>\n\n        <!-- Ticker Strip -->\n        <div class=\"ticker-strip\">\n            <div class=\"ticker-item\">\n                <span class=\"t-name\">NIFTY 50</span>\n                <span class=\"t-val\" id=\"ticker-nifty\">24,350.80</span>\n                <span class=\"t-change pos\" id=\"change-nifty\">+142.30 (+0.59%)</span>\n            </div>\n            <div class=\"ticker-item\">\n                <span class=\"t-name\">BANK NIFTY</span>\n                <span class=\"t-val\" id=\"ticker-banknifty\">52,180.45</span>\n                <span class=\"t-change pos\" id=\"change-banknifty\">+310.15 (+0.60%)</span>\n            </div>\n            <div class=\"ticker-item\">\n                <span class=\"t-name\">INDIA VIX</span>\n                <span class=\"t-val\" id=\"ticker-vix\">12.85</span>\n                <span class=\"t-change neg\" id=\"change-vix\">-0.45 (-3.38%)</span>\n            </div>\n        </div>\n\n        <div class=\"broker-status\">\n            <div class=\"broker-badge upstox\" id=\"broker-badge\">\n                <i class=\"fa-solid fa-bolt\"></i>\n                <span id=\"active-broker-text\">Upstox API v2 Connected</span>\n            </div>\n            <button class=\"btn-primary-sm\" onclick=\"switchTab('broker-config')\">\n                <i class=\"fa-solid fa-key\"></i> Broker API\n            </button>\n        </div>\n    </header>\n\n    <!-- App Container -->\n    <div class=\"app-layout\">\n        <!-- Sidebar Navigation -->\n        <aside class=\"sidebar\">\n            <nav class=\"nav-menu\">\n                <button class=\"nav-btn active\" data-tab=\"chart-studio\" onclick=\"switchTab('chart-studio')\">\n                    <i class=\"fa-solid fa-chart-candlestick\"></i>\n                    <span>Live Chart & Indicators</span>\n                </button>\n                <button class=\"nav-btn\" data-tab=\"strategy-hub\" onclick=\"switchTab('strategy-hub')\">\n                    <i class=\"fa-solid fa-chess\"></i>\n                    <span>Best Strategies & Signals</span>\n                </button>\n                <button class=\"nav-btn\" data-tab=\"backtester\" onclick=\"switchTab('backtester')\">\n                    <i class=\"fa-solid fa-history\"></i>\n                    <span>Strategy Backtester</span>\n                </button>\n                <button class=\"nav-btn\" data-tab=\"risk-calc\" onclick=\"switchTab('risk-calc')\">\n                    <i class=\"fa-solid fa-calculator\"></i>\n                    <span>Risk & Lot Calculator</span>\n                </button>\n                <button class=\"nav-btn\" data-tab=\"use-cases\" onclick=\"switchTab('use-cases')\">\n                    <i class=\"fa-solid fa-lightbulb\"></i>\n                    <span>Why Algo Trading? (For Dad)</span>\n                </button>\n                <button class=\"nav-btn\" data-tab=\"broker-config\" onclick=\"switchTab('broker-config')\">\n                    <i class=\"fa-solid fa-plug\"></i>\n                    <span>Upstox & ICICI Integration</span>\n                </button>\n            </nav>\n\n            <!-- Dad's Quick Summary Box -->\n            <div class=\"dad-summary-box\">\n                <div class=\"d-head\">\n                    <i class=\"fa-solid fa-user-shield\"></i>\n                    <h4>Dad's Safety Guard</h4>\n                </div>\n                <p>Rules set for protection:</p>\n                <ul>\n                    <li><i class=\"fa-solid fa-check\"></i> Max Daily Loss: <b>\u20b910,000</b></li>\n                    <li><i class=\"fa-solid fa-check\"></i> Capital Risk / Trade: <b>1.5%</b></li>\n                    <li><i class=\"fa-solid fa-check\"></i> Auto Stop Loss: <b>Enforced</b></li>\n                    <li><i class=\"fa-solid fa-check\"></i> Emotionless Execution</li>\n                </ul>\n            </div>\n        </aside>\n\n        <!-- Main Content Area -->\n        <main class=\"content-area\">\n\n            <!-- TAB 1: LIVE CHART & INDICATORS -->\n            <section id=\"chart-studio\" class=\"tab-content active\">\n                <!-- Top Chart Control Bar -->\n                <div class=\"chart-controls\">\n                    <div class=\"control-group\">\n                        <label>Symbol:</label>\n                        <select id=\"symbol-select\" onchange=\"updateChartData()\">\n                            <option value=\"NIFTY\">NIFTY 50 Index</option>\n                            <option value=\"BANKNIFTY\">BANK NIFTY Index</option>\n                            <option value=\"RELIANCE\">RELIANCE Industries</option>\n                            <option value=\"TCS\">TCS (Tata Consultancy)</option>\n                            <option value=\"TATAMOTORS\">TATA MOTORS</option>\n                            <option value=\"HDFCBANK\">HDFC BANK</option>\n                        </select>\n                    </div>\n\n                    <div class=\"control-group\">\n                        <label>Timeframe:</label>\n                        <div class=\"btn-group\">\n                            <button class=\"tf-btn\" onclick=\"setTimeframe('1m')\">1M</button>\n                            <button class=\"tf-btn active\" onclick=\"setTimeframe('5m')\">5M</button>\n                            <button class=\"tf-btn\" onclick=\"setTimeframe('15m')\">15M</button>\n                            <button class=\"tf-btn\" onclick=\"setTimeframe('1d')\">1D</button>\n                        </div>\n                    </div>\n\n                    <div class=\"control-group indicator-toggles\">\n                        <label>Indicators:</label>\n                        <button class=\"ind-chip active\" id=\"btn-ema\" onclick=\"toggleIndicator('ema')\">\n                            <i class=\"fa-solid fa-wave-square\"></i> EMA (9/21)\n                        </button>\n                        <button class=\"ind-chip active\" id=\"btn-supertrend\" onclick=\"toggleIndicator('supertrend')\">\n                            <i class=\"fa-solid fa-arrow-trend-up\"></i> Supertrend\n                        </button>\n                        <button class=\"ind-chip active\" id=\"btn-vwap\" onclick=\"toggleIndicator('vwap')\">\n                            <i class=\"fa-solid fa-lines-leaning\"></i> VWAP\n                        </button>\n                        <button class=\"ind-chip\" id=\"btn-bb\" onclick=\"toggleIndicator('bb')\">\n                            <i class=\"fa-solid fa-bars-staggered\"></i> Bollinger Bands\n                        </button>\n                        <button class=\"ind-chip active\" id=\"btn-rsi\" onclick=\"toggleIndicator('rsi')\">\n                            <i class=\"fa-solid fa-gauge-high\"></i> RSI (14)\n                        </button>\n                        <button class=\"ind-chip\" id=\"btn-signals\" onclick=\"toggleIndicator('signals')\">\n                            <i class=\"fa-solid fa-bell\"></i> Buy/Sell Alerts\n                        </button>\n                    </div>\n                </div>\n\n                <!-- Main Chart Grid -->\n                <div class=\"chart-workspace\">\n                    <div class=\"main-chart-card\">\n                        <div class=\"chart-header\">\n                            <div class=\"chart-title\">\n                                <h2 id=\"chart-symbol-name\">NIFTY 50 Index (5M Intraday)</h2>\n                                <span class=\"badge-live\"><i class=\"fa-solid fa-circle\"></i> Live Simulated Feed</span>\n                            </div>\n                            <div class=\"ohlc-display\" id=\"ohlc-readout\">\n                                O: 24,310.50 | H: 24,365.20 | L: 24,295.10 | C: 24,350.80\n                            </div>\n                        </div>\n\n                        <!-- Canvas Chart Area -->\n                        <div class=\"canvas-container\">\n                            <canvas id=\"mainChartCanvas\"></canvas>\n                        </div>\n\n                        <!-- Sub Chart Area (RSI / MACD) -->\n                        <div class=\"sub-chart-container\" id=\"rsi-container\">\n                            <div class=\"sub-chart-title\">\n                                <span>RSI (14 Period) - Overbought > 70 | Oversold < 30</span>\n                                <span id=\"rsi-value-text\" class=\"rsi-val\">RSI: 58.42</span>\n                            </div>\n                            <canvas id=\"rsiCanvas\"></canvas>\n                        </div>\n                    </div>\n\n                    <!-- Right Side Signal & Order Panel -->\n                    <div class=\"chart-sidebar\">\n                        <div class=\"card signal-box\">\n                            <div class=\"card-header\">\n                                <h3><i class=\"fa-solid fa-robot\"></i> Live Algo Signal</h3>\n                                <span class=\"badge-status buy\" id=\"signal-badge\">BUY SIGNAL</span>\n                            </div>\n                            <div class=\"signal-details\">\n                                <div class=\"sig-row\">\n                                    <span>Trigger Strategy:</span>\n                                    <strong id=\"sig-strategy\">EMA Golden Crossover + RSI</strong>\n                                </div>\n                                <div class=\"sig-row\">\n                                    <span>Entry Price:</span>\n                                    <strong id=\"sig-entry\" class=\"highlight\">\u20b924,340.00</strong>\n                                </div>\n                                <div class=\"sig-row\">\n                                    <span>Stop Loss (SL):</span>\n                                    <strong id=\"sig-sl\" class=\"danger\">\u20b924,290.00 (-50 pts)</strong>\n                                </div>\n                                <div class=\"sig-row\">\n                                    <span>Target 1 (1:2):</span>\n                                    <strong id=\"sig-tp\" class=\"success\">\u20b924,440.00 (+100 pts)</strong>\n                                </div>\n                                <div class=\"sig-row\">\n                                    <span>Risk-Reward Ratio:</span>\n                                    <strong>1 : 2.0</strong>\n                                </div>\n                            </div>\n                            <button class=\"btn-execute-buy\" onclick=\"simulateOrder('BUY')\">\n                                <i class=\"fa-solid fa-bolt\"></i> Auto-Execute BUY Order (Upstox/ICICI)\n                            </button>\n                            <button class=\"btn-execute-sell\" onclick=\"simulateOrder('SELL')\">\n                                <i class=\"fa-solid fa-arrow-down-short-wide\"></i> Auto-Execute SELL Order\n                            </button>\n                        </div>\n\n                        <!-- Active Positions Card -->\n                        <div class=\"card active-positions\">\n                            <div class=\"card-header\">\n                                <h3><i class=\"fa-solid fa-briefcase\"></i> Active Positions</h3>\n                                <span class=\"pos-pnl positive\" id=\"total-pnl\">+\u20b94,500.00</span>\n                            </div>\n                            <div class=\"position-list\" id=\"positions-container\">\n                                <div class=\"pos-item\">\n                                    <div class=\"pos-top\">\n                                        <span class=\"pos-sym\">NIFTY 24350 CE</span>\n                                        <span class=\"pos-qty\">150 Qty (3 Lots)</span>\n                                    </div>\n                                    <div class=\"pos-bottom\">\n                                        <span>Avg: \u20b9125.40 | LTP: \u20b9155.40</span>\n                                        <span class=\"pos-gain\">+\u20b94,500 (+23.9%)</span>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- TAB 2: BEST STRATEGIES & SIGNALS -->\n            <section id=\"strategy-hub\" class=\"tab-content\">\n                <div class=\"section-title\">\n                    <h2><i class=\"fa-solid fa-chess-king\"></i> Top Proven Algo Strategies for Indian Markets</h2>\n                    <p>Designed for maximum probability, tight risk management, and automatic execution on Upstox / ICICI Direct.</p>\n                </div>\n\n                <div class=\"strategies-grid\">\n                    <!-- Strategy 1 -->\n                    <div class=\"strategy-card featured\">\n                        <div class=\"strat-header\">\n                            <div class=\"strat-title\">\n                                <span class=\"strat-tag\">Most Popular for Intraday</span>\n                                <h3>1. EMA Golden Crossover + RSI Filter</h3>\n                            </div>\n                            <span class=\"strat-winrate\">71.4% Win Rate</span>\n                        </div>\n                        <p class=\"strat-desc\">Triggers a BUY order when 9-period EMA crosses above 21-period EMA while RSI is above 50 (confirming bullish momentum).</p>\n                        <div class=\"rule-box\">\n                            <div><strong><i class=\"fa-solid fa-arrow-trend-up success\"></i> BUY Rule:</strong> EMA 9 > EMA 21 AND RSI > 50 AND Price > VWAP</div>\n                            <div><strong><i class=\"fa-solid fa-arrow-trend-down danger\"></i> SELL Rule:</strong> EMA 9 < EMA 21 OR RSI < 40</div>\n                        </div>\n                        <div class=\"strat-stats\">\n                            <div><span>Avg Profit:</span> <strong>1 : 2.2 R:R</strong></div>\n                            <div><span>Best For:</span> <strong>NIFTY, BANKNIFTY & High Beta Stocks</strong></div>\n                            <div><span>Timeframe:</span> <strong>5 Min / 15 Min</strong></div>\n                        </div>\n                    </div>\n\n                    <!-- Strategy 2 -->\n                    <div class=\"strategy-card\">\n                        <div class=\"strat-header\">\n                            <div class=\"strat-title\">\n                                <span class=\"strat-tag\">Trend Following</span>\n                                <h3>2. Supertrend (10, 3) + VWAP Breakout</h3>\n                            </div>\n                            <span class=\"strat-winrate\">68.2% Win Rate</span>\n                        </div>\n                        <p class=\"strat-desc\">Combines institutional volume benchmark (VWAP) with Supertrend reversal to capture strong multi-hour directional moves.</p>\n                        <div class=\"rule-box\">\n                            <div><strong><i class=\"fa-solid fa-arrow-trend-up success\"></i> BUY Rule:</strong> Supertrend turns GREEN AND Candle Closes Above VWAP</div>\n                            <div><strong><i class=\"fa-solid fa-arrow-trend-down danger\"></i> SELL Rule:</strong> Supertrend turns RED OR Price breaks below VWAP</div>\n                        </div>\n                        <div class=\"strat-stats\">\n                            <div><span>Avg Profit:</span> <strong>1 : 2.5 R:R</strong></div>\n                            <div><span>Best For:</span> <strong>Trending Days / Bank Nifty Options</strong></div>\n                            <div><span>Timeframe:</span> <strong>15 Min</strong></div>\n                        </div>\n                    </div>\n\n                    <!-- Strategy 3 -->\n                    <div class=\"strategy-card\">\n                        <div class=\"strat-header\">\n                            <div class=\"strat-title\">\n                                <span class=\"strat-tag\">Range & Sideways</span>\n                                <h3>3. Bollinger Band Squeeze & Reversal</h3>\n                            </div>\n                            <span class=\"strat-winrate\">64.8% Win Rate</span>\n                        </div>\n                        <p class=\"strat-desc\">Identifies low-volatility compression bands and buys oversold bounces off the lower band when RSI < 35.</p>\n                        <div class=\"rule-box\">\n                            <div><strong><i class=\"fa-solid fa-arrow-trend-up success\"></i> BUY Rule:</strong> Price touches Lower Bollinger Band AND RSI < 35</div>\n                            <div><strong><i class=\"fa-solid fa-arrow-trend-down danger\"></i> SELL Rule:</strong> Price touches Upper Bollinger Band OR RSI > 65</div>\n                        </div>\n                        <div class=\"strat-stats\">\n                            <div><span>Avg Profit:</span> <strong>1 : 1.8 R:R</strong></div>\n                            <div><span>Best For:</span> <strong>Non-Trending / Range-Bound Stocks</strong></div>\n                            <div><span>Timeframe:</span> <strong>5 Min</strong></div>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- TAB 3: STRATEGY BACKTESTER -->\n            <section id=\"backtester\" class=\"tab-content\">\n                <div class=\"section-title\">\n                    <h2><i class=\"fa-solid fa-history\"></i> Algorithmic Strategy Backtester</h2>\n                    <p>Test any strategy against historical market data to verify profitability before risking real money.</p>\n                </div>\n\n                <div class=\"backtest-grid\">\n                    <!-- Config Panel -->\n                    <div class=\"card bt-config\">\n                        <h3><i class=\"fa-solid fa-sliders\"></i> Backtest Parameters</h3>\n                        <div class=\"form-group\">\n                            <label>Strategy:</label>\n                            <select id=\"bt-strategy\">\n                                <option value=\"ema\">EMA 9/21 Crossover + RSI</option>\n                                <option value=\"supertrend\">Supertrend + VWAP</option>\n                                <option value=\"bb\">Bollinger Bands Mean Reversion</option>\n                            </select>\n                        </div>\n                        <div class=\"form-group\">\n                            <label>Stock / Index:</label>\n                            <select id=\"bt-symbol\">\n                                <option value=\"NIFTY\">NIFTY 50</option>\n                                <option value=\"BANKNIFTY\">BANK NIFTY</option>\n                                <option value=\"RELIANCE\">RELIANCE</option>\n                                <option value=\"TCS\">TCS</option>\n                            </select>\n                        </div>\n                        <div class=\"form-group\">\n                            <label>Starting Capital (\u20b9):</label>\n                            <input type=\"number\" id=\"bt-capital\" value=\"500000\">\n                        </div>\n                        <div class=\"form-group\">\n                            <label>Risk Per Trade (%):</label>\n                            <input type=\"number\" id=\"bt-risk\" value=\"1.5\" step=\"0.1\">\n                        </div>\n                        <button class=\"btn-primary\" onclick=\"runBacktest()\">\n                            <i class=\"fa-solid fa-play\"></i> Run Historical Backtest\n                        </button>\n                    </div>\n\n                    <!-- Metrics Summary -->\n                    <div class=\"card bt-results\">\n                        <h3><i class=\"fa-solid fa-trophy\"></i> Backtest Performance Summary</h3>\n                        <div class=\"metrics-grid\">\n                            <div class=\"metric-card\">\n                                <span>Total Net Profit</span>\n                                <h3 id=\"bt-net-profit\" class=\"success\">+\u20b91,42,850.00</h3>\n                                <small>+28.57% Capital Growth</small>\n                            </div>\n                            <div class=\"metric-card\">\n                                <span>Win Rate</span>\n                                <h3 id=\"bt-winrate\">69.2%</h3>\n                                <small>36 Wins / 16 Losses</small>\n                            </div>\n                            <div class=\"metric-card\">\n                                <span>Profit Factor</span>\n                                <h3 id=\"bt-pf\">2.34</h3>\n                                <small>Gross Profit / Gross Loss</small>\n                            </div>\n                            <div class=\"metric-card\">\n                                <span>Max Drawdown</span>\n                                <h3 id=\"bt-drawdown\" class=\"danger\">-4.8%</h3>\n                                <small>Peak-to-trough decline</small>\n                            </div>\n                        </div>\n\n                        <div class=\"equity-chart-box\">\n                            <h4>Equity Growth Curve (12 Months Historical)</h4>\n                            <canvas id=\"equityCanvas\" height=\"150\"></canvas>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- TAB 4: RISK & LOT CALCULATOR -->\n            <section id=\"risk-calc\" class=\"tab-content\">\n                <div class=\"section-title\">\n                    <h2><i class=\"fa-solid fa-calculator\"></i> Capital Protection & Lot Size Calculator</h2>\n                    <p>Calculates exact quantity to buy so you NEVER exceed your risk limit on any trade.</p>\n                </div>\n\n                <div class=\"calc-grid\">\n                    <div class=\"card calc-form\">\n                        <h3><i class=\"fa-solid fa-coins\"></i> Input Trade Parameters</h3>\n                        <div class=\"form-group\">\n                            <label>Total Account Balance (\u20b9):</label>\n                            <input type=\"number\" id=\"calc-account\" value=\"500000\" oninput=\"calculateRisk()\">\n                        </div>\n                        <div class=\"form-group\">\n                            <label>Risk Per Trade (%):</label>\n                            <input type=\"number\" id=\"calc-risk-pct\" value=\"1.5\" step=\"0.1\" oninput=\"calculateRisk()\">\n                        </div>\n                        <div class=\"form-group\">\n                            <label>Entry Price (\u20b9):</label>\n                            <input type=\"number\" id=\"calc-entry\" value=\"24340\" oninput=\"calculateRisk()\">\n                        </div>\n                        <div class=\"form-group\">\n                            <label>Stop Loss Price (\u20b9):</label>\n                            <input type=\"number\" id=\"calc-sl\" value=\"24290\" oninput=\"calculateRisk()\">\n                        </div>\n                        <div class=\"form-group\">\n                            <label>Target Price (\u20b9):</label>\n                            <input type=\"number\" id=\"calc-target\" value=\"24440\" oninput=\"calculateRisk()\">\n                        </div>\n                    </div>\n\n                    <div class=\"card calc-output\">\n                        <h3><i class=\"fa-solid fa-shield-halved\"></i> Recommended Order Parameters</h3>\n                        <div class=\"calc-result-box\">\n                            <div class=\"res-item\">\n                                <span>Max Allowed Loss on Trade:</span>\n                                <h3 class=\"danger\" id=\"res-max-loss\">\u20b97,500.00</h3>\n                            </div>\n                            <div class=\"res-item\">\n                                <span>SL Points (Risk per share):</span>\n                                <h3 id=\"res-sl-points\">50.00 Pts</h3>\n                            </div>\n                            <div class=\"res-item highlight\">\n                                <span>Recommended Share Qty:</span>\n                                <h2 id=\"res-qty\">150 Shares</h2>\n                                <small id=\"res-lots\">(3 NIFTY Lots of 50)</small>\n                            </div>\n                            <div class=\"res-item\">\n                                <span>Expected Target Profit:</span>\n                                <h3 class=\"success\" id=\"res-expected-profit\">\u20b915,000.00</h3>\n                            </div>\n                            <div class=\"res-item\">\n                                <span>Risk to Reward Ratio:</span>\n                                <h3 class=\"highlight\" id=\"res-rr\">1 : 2.0</h3>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- TAB 5: WHY ALGO TRADING (FOR DAD) -->\n            <section id=\"use-cases\" class=\"tab-content\">\n                <div class=\"section-title\">\n                    <h2><i class=\"fa-solid fa-heart\"></i> Why Algo Trading is Safer & Better for Dad</h2>\n                    <p>Key benefits of automated trading compared to traditional manual emotional trading.</p>\n                </div>\n\n                <div class=\"dad-cards-grid\">\n                    <div class=\"dad-card\">\n                        <div class=\"d-icon\"><i class=\"fa-solid fa-brain-circuit\"></i></div>\n                        <h3>1. Zero Emotional Errors</h3>\n                        <p>Most traders lose money due to <b>Fear and Greed</b> \u2014 holding losing stocks hoping they recover, or selling winners too early. Algos execute strictly based on logic.</p>\n                    </div>\n\n                    <div class=\"dad-card\">\n                        <div class=\"d-icon\"><i class=\"fa-solid fa-shield-virus\"></i></div>\n                        <h3>2. Hard Stop Loss Guard</h3>\n                        <p>If a stock drops suddenly, a human trader hesitates. The algo cuts the trade instantly at the pre-set Stop Loss, preserving 98%+ of capital.</p>\n                    </div>\n\n                    <div class=\"dad-card\">\n                        <div class=\"d-icon\"><i class=\"fa-solid fa-bolt-lightning\"></i></div>\n                        <h3>3. Lightning Fast Speed</h3>\n                        <p>Brokers like <b>Upstox</b> and <b>ICICI Direct</b> process API orders in less than 50 milliseconds. Manual typing can take 5-10 seconds, causing bad fills.</p>\n                    </div>\n\n                    <div class=\"dad-card\">\n                        <div class=\"d-icon\"><i class=\"fa-solid fa-vial-circle-check\"></i></div>\n                        <h3>4. Tested Before Real Money</h3>\n                        <p>You can backtest strategies on 5 years of historical Indian market data to verify they actually make money before spending \u20b91 of real capital.</p>\n                    </div>\n\n                    <div class=\"dad-card\">\n                        <div class=\"d-icon\"><i class=\"fa-solid fa-clock-rotate-left\"></i></div>\n                        <h3>5. Freedom & Time Saving</h3>\n                        <p>No need to sit glued to screens for 6 hours daily. The algorithm scans markets, alerts you, and manages positions automatically.</p>\n                    </div>\n\n                    <div class=\"dad-card\">\n                        <div class=\"d-icon\"><i class=\"fa-solid fa-lock\"></i></div>\n                        <h3>6. Daily Loss Circuit Breaker</h3>\n                        <p>If total daily losses hit a set limit (e.g. \u20b910,000), the bot automatically turns off for the day. No revenge trading!</p>\n                    </div>\n                </div>\n            </section>\n\n            <!-- TAB 6: UPSTOX & ICICI INTEGRATION -->\n            <section id=\"broker-config\" class=\"tab-content\">\n                <div class=\"section-title\">\n                    <h2><i class=\"fa-solid fa-plug\"></i> Upstox API v2 & ICICI Direct Breeze Connection</h2>\n                    <p>Connect your active broker account to enable auto-trading via official Python SDKs.</p>\n                </div>\n\n                <div class=\"broker-tabs\">\n                    <div class=\"b-tab-buttons\">\n                        <button class=\"b-tab active\" onclick=\"showBrokerTab('upstox')\">\n                            <img src=\"https://upstox.com/app/uploads/2021/04/upstox-favicon.png\" width=\"20\" height=\"20\" alt=\"Upstox\" onerror=\"this.style.display='none'\"> Upstox API v2\n                        </button>\n                        <button class=\"b-tab\" onclick=\"showBrokerTab('icici')\">\n                            <i class=\"fa-solid fa-building-columns\"></i> ICICI Direct Breeze API\n                        </button>\n                    </div>\n\n                    <!-- Upstox Panel -->\n                    <div id=\"broker-upstox\" class=\"broker-panel active\">\n                        <div class=\"card\">\n                            <h3><i class=\"fa-solid fa-key\"></i> Upstox Developer Credentials</h3>\n                            <div class=\"form-grid\">\n                                <div class=\"form-group\">\n                                    <label>API Key:</label>\n                                    <input type=\"text\" id=\"upstox-api-key\" placeholder=\"e.g. 5d9f0a2e-812d-4b91-9c88-...\" value=\"upstox_live_api_key_demo\">\n                                </div>\n                                <div class=\"form-group\">\n                                    <label>API Secret:</label>\n                                    <input type=\"password\" id=\"upstox-api-secret\" value=\"upstox_secret_demo_12345\">\n                                </div>\n                                <div class=\"form-group\">\n                                    <label>Redirect URI:</label>\n                                    <input type=\"text\" id=\"upstox-redirect\" value=\"http://127.0.0.1:5000/callback\">\n                                </div>\n                            </div>\n                            <button class=\"btn-primary\" onclick=\"testBrokerAuth('Upstox')\">\n                                <i class=\"fa-solid fa-plug-circle-check\"></i> Connect Upstox Account\n                            </button>\n                        </div>\n\n                        <div class=\"code-box\">\n                            <div class=\"code-header\">\n                                <span><i class=\"fa-brands fa-python\"></i> upstox_algo_bot.py (Ready to Run Python Script)</span>\n                                <button class=\"btn-copy\" onclick=\"copyCode('upstox-code')\"><i class=\"fa-solid fa-copy\"></i> Copy Code</button>\n                            </div>\n                            <pre><code id=\"upstox-code\">import upstox_client\nfrom upstox_client.rest import ApiException\n\n# 1. Initialize Upstox API Configuration\nconfiguration = upstox_client.Configuration()\nconfiguration.access_token = 'YOUR_DAILY_ACCESS_TOKEN'\n\napi_instance = upstox_client.OrderApi(upstox_client.ApiClient(configuration))\n\n# 2. Define Auto BUY Order Function\ndef place_algo_buy_order(symbol_key, qty, trigger_price):\n    body = upstox_client.PlaceOrderRequest(\n        quantity=qty,\n        product='I', # 'I' for Intraday, 'D' for Delivery\n        validity='DAY',\n        price=trigger_price,\n        tag='ZENITH_ALGO',\n        instrument_token=symbol_key,\n        order_type='LIMIT',\n        transaction_type='BUY',\n        disclosed_quantity=0,\n        trigger_price=0.0,\n        is_amo=False\n    )\n    try:\n        api_response = api_instance.place_order(body, api_version='2.0')\n        print(f\"\u2705 BUY Order Executed! Order ID: {api_response.data.order_id}\")\n        return api_response.data.order_id\n    except ApiException as e:\n        print(f\"\u274c Exception when placing order: {e}\")\n\n# Example Execution\n# place_algo_buy_order('NSE_EQ|INE002A01018', 50, 24340.0)</code></pre>\n                        </div>\n                    </div>\n\n                    <!-- ICICI Breeze Panel -->\n                    <div id=\"broker-icici\" class=\"broker-panel\">\n                        <div class=\"card\">\n                            <h3><i class=\"fa-solid fa-key\"></i> ICICI Breeze Credentials</h3>\n                            <div class=\"form-grid\">\n                                <div class=\"form-group\">\n                                    <label>App Key:</label>\n                                    <input type=\"text\" id=\"icici-app-key\" value=\"icici_breeze_app_key_demo\">\n                                </div>\n                                <div class=\"form-group\">\n                                    <label>Secret Key:</label>\n                                    <input type=\"password\" id=\"icici-secret-key\" value=\"icici_secret_demo_9876\">\n                                </div>\n                                <div class=\"form-group\">\n                                    <label>Session Token:</label>\n                                    <input type=\"text\" id=\"icici-session\" placeholder=\"Daily Session Token\">\n                                </div>\n                            </div>\n                            <button class=\"btn-primary\" onclick=\"testBrokerAuth('ICICI Direct Breeze')\">\n                                <i class=\"fa-solid fa-plug-circle-check\"></i> Connect ICICI Breeze Account\n                            </button>\n                        </div>\n\n                        <div class=\"code-box\">\n                            <div class=\"code-header\">\n                                <span><i class=\"fa-brands fa-python\"></i> icici_breeze_bot.py (Ready to Run Python Script)</span>\n                                <button class=\"btn-copy\" onclick=\"copyCode('icici-code')\"><i class=\"fa-solid fa-copy\"></i> Copy Code</button>\n                            </div>\n                            <pre><code id=\"icici-code\">from breeze_connect import BreezeConnect\n\n# 1. Initialize Breeze Connect SDK\nbreeze = BreezeConnect(api_key=\"YOUR_APP_KEY\")\nbreeze.generate_session(api_secret=\"YOUR_SECRET_KEY\", session_token=\"YOUR_SESSION_TOKEN\")\n\n# 2. Place Order on ICICI Direct\ndef place_breeze_buy_order(stock_code, qty, price):\n    response = breeze.place_order(\n        stock_code=stock_code,       # e.g., 'NIFTY' or 'RELIANCE'\n        exchange_code=\"NSE\",\n        product=\"margin\",            # 'margin' for intraday, 'cash' for delivery\n        action=\"buy\",\n        order_type=\"limit\",\n        stoploss=\"0\",\n        quantity=str(qty),\n        price=str(price),\n        validity=\"day\"\n    )\n    print(\"\u2705 ICICI Breeze Order Response:\", response)\n    return response\n\n# Example Execution\n# place_breeze_buy_order('NIFTY', 150, 24340.0)</code></pre>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n        </main>\n    </div>\n\n    <!-- Notification Toasts -->\n    <div id=\"toast-container\"></div>\n\n    <script src=\"app.js\"></script>\n</body>\n</html>\n",
  "style.css": "/* ==========================================================================\n   ZenithAlgo Pro - Premium Dark Glassmorphism CSS Architecture\n   ========================================================================== */\n\n:root {\n    --bg-main: #0b0f19;\n    --bg-secondary: #111827;\n    --bg-card: rgba(17, 24, 39, 0.75);\n    --bg-card-hover: rgba(31, 41, 55, 0.85);\n    --border-color: rgba(255, 255, 255, 0.08);\n    --border-accent: rgba(59, 130, 246, 0.3);\n    \n    --primary: #3b82f6;\n    --primary-glow: rgba(59, 130, 246, 0.4);\n    --success: #10b981;\n    --success-glow: rgba(16, 185, 129, 0.4);\n    --danger: #ef4444;\n    --danger-glow: rgba(239, 68, 68, 0.4);\n    --warning: #f59e0b;\n    --accent: #8b5cf6;\n    \n    --text-main: #f9fafb;\n    --text-muted: #9ca3af;\n    --text-sub: #6b7280;\n    \n    --font-sans: 'Outfit', -apple-system, BlinkMacSystemFont, sans-serif;\n    --font-mono: 'JetBrains Mono', monospace;\n}\n\n* {\n    margin: 0;\n    padding: 0;\n    box-sizing: border-box;\n}\n\nbody {\n    font-family: var(--font-sans);\n    background-color: var(--bg-main);\n    color: var(--text-main);\n    height: 100vh;\n    overflow-x: hidden;\n    background-image: \n        radial-gradient(circle at 10% 20%, rgba(59, 130, 246, 0.05) 0%, transparent 40%),\n        radial-gradient(circle at 90% 80%, rgba(139, 92, 246, 0.05) 0%, transparent 40%);\n}\n\n/* ==================== Top Navbar ==================== */\n.navbar {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    padding: 0.75rem 1.5rem;\n    background: rgba(17, 24, 39, 0.9);\n    backdrop-filter: blur(12px);\n    border-bottom: 1px solid var(--border-color);\n    position: sticky;\n    top: 0;\n    z-index: 100;\n}\n\n.brand {\n    display: flex;\n    align-items: center;\n    gap: 0.75rem;\n}\n\n.logo-icon {\n    width: 42px;\n    height: 42px;\n    background: linear-gradient(135deg, var(--primary), var(--accent));\n    border-radius: 10px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 1.25rem;\n    color: #fff;\n    box-shadow: 0 0 15px var(--primary-glow);\n}\n\n.brand-text h1 {\n    font-size: 1.25rem;\n    font-weight: 700;\n    letter-spacing: 1px;\n}\n\n.brand-text h1 span {\n    color: var(--primary);\n}\n\n.brand-text p {\n    font-size: 0.75rem;\n    color: var(--text-muted);\n}\n\n.ticker-strip {\n    display: flex;\n    gap: 1.5rem;\n    background: rgba(255, 255, 255, 0.03);\n    padding: 0.4rem 1.25rem;\n    border-radius: 30px;\n    border: 1px solid var(--border-color);\n}\n\n.ticker-item {\n    display: flex;\n    align-items: center;\n    gap: 0.5rem;\n    font-size: 0.85rem;\n}\n\n.t-name {\n    font-weight: 600;\n    color: var(--text-muted);\n}\n\n.t-val {\n    font-family: var(--font-mono);\n    font-weight: 600;\n}\n\n.t-change.pos {\n    color: var(--success);\n}\n\n.t-change.neg {\n    color: var(--danger);\n}\n\n.broker-status {\n    display: flex;\n    align-items: center;\n    gap: 1rem;\n}\n\n.broker-badge {\n    display: flex;\n    align-items: center;\n    gap: 0.5rem;\n    padding: 0.4rem 0.85rem;\n    border-radius: 20px;\n    font-size: 0.8rem;\n    font-weight: 600;\n    background: rgba(16, 185, 129, 0.15);\n    color: var(--success);\n    border: 1px solid rgba(16, 185, 129, 0.3);\n}\n\n/* ==================== App Layout ==================== */\n.app-layout {\n    display: grid;\n    grid-template-columns: 260px 1fr;\n    height: calc(100vh - 65px);\n}\n\n/* Sidebar */\n.sidebar {\n    background: rgba(17, 24, 39, 0.8);\n    border-right: 1px solid var(--border-color);\n    padding: 1.25rem 0.75rem;\n    display: flex;\n    flex-direction: column;\n    justify-content: space-between;\n}\n\n.nav-menu {\n    display: flex;\n    flex-direction: column;\n    gap: 0.4rem;\n}\n\n.nav-btn {\n    display: flex;\n    align-items: center;\n    gap: 0.85rem;\n    padding: 0.75rem 1rem;\n    background: transparent;\n    border: none;\n    color: var(--text-muted);\n    font-family: var(--font-sans);\n    font-size: 0.9rem;\n    font-weight: 500;\n    border-radius: 10px;\n    cursor: pointer;\n    transition: all 0.2s ease;\n    text-align: left;\n}\n\n.nav-btn i {\n    font-size: 1.1rem;\n    width: 20px;\n}\n\n.nav-btn:hover {\n    background: rgba(255, 255, 255, 0.05);\n    color: var(--text-main);\n}\n\n.nav-btn.active {\n    background: linear-gradient(135deg, rgba(59, 130, 246, 0.2), rgba(139, 92, 246, 0.15));\n    color: var(--primary);\n    border: 1px solid var(--border-accent);\n    box-shadow: 0 4px 12px rgba(59, 130, 246, 0.15);\n}\n\n.dad-summary-box {\n    background: rgba(16, 185, 129, 0.08);\n    border: 1px solid rgba(16, 185, 129, 0.2);\n    border-radius: 12px;\n    padding: 1rem;\n}\n\n.d-head {\n    display: flex;\n    align-items: center;\n    gap: 0.5rem;\n    color: var(--success);\n    margin-bottom: 0.5rem;\n}\n\n.dad-summary-box p {\n    font-size: 0.75rem;\n    color: var(--text-muted);\n    margin-bottom: 0.5rem;\n}\n\n.dad-summary-box ul {\n    list-style: none;\n    font-size: 0.75rem;\n}\n\n.dad-summary-box li {\n    display: flex;\n    align-items: center;\n    gap: 0.4rem;\n    margin-bottom: 0.3rem;\n}\n\n.dad-summary-box li i {\n    color: var(--success);\n    font-size: 0.7rem;\n}\n\n/* Main Content */\n.content-area {\n    padding: 1.25rem;\n    overflow-y: auto;\n}\n\n.tab-content {\n    display: none;\n    animation: fadeIn 0.3s ease;\n}\n\n.tab-content.active {\n    display: block;\n}\n\n@keyframes fadeIn {\n    from { opacity: 0; transform: translateY(6px); }\n    to { opacity: 1; transform: translateY(0); }\n}\n\n/* Buttons */\n.btn-primary {\n    background: linear-gradient(135deg, var(--primary), #2563eb);\n    color: #fff;\n    border: none;\n    padding: 0.75rem 1.5rem;\n    border-radius: 8px;\n    font-family: var(--font-sans);\n    font-weight: 600;\n    cursor: pointer;\n    transition: all 0.2s ease;\n    box-shadow: 0 4px 12px var(--primary-glow);\n    display: inline-flex;\n    align-items: center;\n    gap: 0.5rem;\n}\n\n.btn-primary:hover {\n    transform: translateY(-2px);\n    box-shadow: 0 6px 18px var(--primary-glow);\n}\n\n.btn-primary-sm {\n    background: rgba(59, 130, 246, 0.15);\n    color: var(--primary);\n    border: 1px solid var(--border-accent);\n    padding: 0.4rem 0.85rem;\n    border-radius: 8px;\n    font-size: 0.8rem;\n    font-weight: 600;\n    cursor: pointer;\n    transition: all 0.2s ease;\n}\n\n.btn-primary-sm:hover {\n    background: var(--primary);\n    color: #fff;\n}\n\n/* Section Titles */\n.section-title {\n    margin-bottom: 1.5rem;\n}\n\n.section-title h2 {\n    font-size: 1.5rem;\n    font-weight: 700;\n    display: flex;\n    align-items: center;\n    gap: 0.6rem;\n}\n\n.section-title p {\n    color: var(--text-muted);\n    font-size: 0.9rem;\n    margin-top: 0.25rem;\n}\n\n/* ==================== TAB 1: CHART STUDIO ==================== */\n.chart-controls {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    background: var(--bg-card);\n    border: 1px solid var(--border-color);\n    padding: 0.75rem 1.25rem;\n    border-radius: 12px;\n    margin-bottom: 1rem;\n    flex-wrap: wrap;\n    gap: 1rem;\n}\n\n.control-group {\n    display: flex;\n    align-items: center;\n    gap: 0.6rem;\n}\n\n.control-group label {\n    font-size: 0.8rem;\n    font-weight: 600;\n    color: var(--text-muted);\n    text-transform: uppercase;\n}\n\nselect, input {\n    background: rgba(0, 0, 0, 0.4);\n    border: 1px solid var(--border-color);\n    color: var(--text-main);\n    padding: 0.45rem 0.85rem;\n    border-radius: 8px;\n    font-family: var(--font-sans);\n    font-size: 0.85rem;\n    outline: none;\n}\n\nselect:focus, input:focus {\n    border-color: var(--primary);\n}\n\n.btn-group {\n    display: flex;\n    background: rgba(0, 0, 0, 0.4);\n    border-radius: 8px;\n    padding: 2px;\n}\n\n.tf-btn {\n    background: transparent;\n    border: none;\n    color: var(--text-muted);\n    padding: 0.35rem 0.75rem;\n    font-size: 0.75rem;\n    font-weight: 600;\n    border-radius: 6px;\n    cursor: pointer;\n}\n\n.tf-btn.active {\n    background: var(--primary);\n    color: #fff;\n}\n\n.indicator-toggles {\n    display: flex;\n    gap: 0.4rem;\n}\n\n.ind-chip {\n    background: rgba(255, 255, 255, 0.05);\n    border: 1px solid var(--border-color);\n    color: var(--text-muted);\n    padding: 0.4rem 0.75rem;\n    border-radius: 20px;\n    font-size: 0.75rem;\n    font-weight: 600;\n    cursor: pointer;\n    transition: all 0.2s ease;\n}\n\n.ind-chip.active {\n    background: rgba(59, 130, 246, 0.2);\n    color: var(--primary);\n    border-color: var(--border-accent);\n}\n\n.chart-workspace {\n    display: grid;\n    grid-template-columns: 1fr 340px;\n    gap: 1rem;\n    height: calc(100vh - 220px);\n}\n\n.main-chart-card {\n    background: var(--bg-card);\n    border: 1px solid var(--border-color);\n    border-radius: 14px;\n    padding: 1rem;\n    display: flex;\n    flex-direction: column;\n    gap: 0.75rem;\n}\n\n.chart-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    border-bottom: 1px solid var(--border-color);\n    padding-bottom: 0.6rem;\n}\n\n.chart-title h2 {\n    font-size: 1.1rem;\n    font-weight: 600;\n}\n\n.badge-live {\n    font-size: 0.7rem;\n    color: var(--success);\n    display: flex;\n    align-items: center;\n    gap: 0.3rem;\n    font-weight: 600;\n}\n\n.badge-live i {\n    font-size: 0.5rem;\n    animation: pulse 1.5s infinite;\n}\n\n@keyframes pulse {\n    0% { opacity: 0.3; }\n    50% { opacity: 1; }\n    100% { opacity: 0.3; }\n}\n\n.ohlc-display {\n    font-family: var(--font-mono);\n    font-size: 0.8rem;\n    color: var(--text-muted);\n}\n\n.canvas-container {\n    flex: 1;\n    position: relative;\n    width: 100%;\n    min-height: 280px;\n}\n\n#mainChartCanvas {\n    width: 100%;\n    height: 100%;\n    border-radius: 8px;\n}\n\n.sub-chart-container {\n    height: 120px;\n    border-top: 1px solid var(--border-color);\n    padding-top: 0.5rem;\n    display: flex;\n    flex-direction: column;\n}\n\n.sub-chart-title {\n    display: flex;\n    justify-content: space-between;\n    font-size: 0.75rem;\n    color: var(--text-muted);\n    margin-bottom: 0.3rem;\n}\n\n.rsi-val {\n    color: var(--primary);\n    font-family: var(--font-mono);\n    font-weight: 600;\n}\n\n#rsiCanvas {\n    width: 100%;\n    height: 100%;\n}\n\n/* Sidebar Signals */\n.chart-sidebar {\n    display: flex;\n    flex-direction: column;\n    gap: 1rem;\n}\n\n.card {\n    background: var(--bg-card);\n    border: 1px solid var(--border-color);\n    border-radius: 14px;\n    padding: 1.25rem;\n}\n\n.card-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    margin-bottom: 1rem;\n}\n\n.card-header h3 {\n    font-size: 1rem;\n    font-weight: 600;\n    display: flex;\n    align-items: center;\n    gap: 0.5rem;\n}\n\n.badge-status.buy {\n    background: rgba(16, 185, 129, 0.2);\n    color: var(--success);\n    border: 1px solid rgba(16, 185, 129, 0.4);\n    padding: 0.2rem 0.6rem;\n    border-radius: 12px;\n    font-size: 0.7rem;\n    font-weight: 700;\n}\n\n.signal-details {\n    display: flex;\n    flex-direction: column;\n    gap: 0.6rem;\n    font-size: 0.85rem;\n    margin-bottom: 1.25rem;\n    background: rgba(0, 0, 0, 0.3);\n    padding: 0.85rem;\n    border-radius: 10px;\n}\n\n.sig-row {\n    display: flex;\n    justify-content: space-between;\n}\n\n.sig-row span {\n    color: var(--text-muted);\n}\n\n.highlight { color: var(--primary); font-family: var(--font-mono); }\n.success { color: var(--success); font-family: var(--font-mono); }\n.danger { color: var(--danger); font-family: var(--font-mono); }\n\n.btn-execute-buy {\n    width: 100%;\n    background: linear-gradient(135deg, var(--success), #059669);\n    color: #fff;\n    border: none;\n    padding: 0.75rem;\n    border-radius: 10px;\n    font-weight: 700;\n    cursor: pointer;\n    margin-bottom: 0.5rem;\n    box-shadow: 0 4px 12px var(--success-glow);\n    transition: all 0.2s ease;\n}\n\n.btn-execute-buy:hover {\n    transform: translateY(-2px);\n    box-shadow: 0 6px 18px var(--success-glow);\n}\n\n.btn-execute-sell {\n    width: 100%;\n    background: rgba(239, 68, 68, 0.15);\n    color: var(--danger);\n    border: 1px solid rgba(239, 68, 68, 0.3);\n    padding: 0.6rem;\n    border-radius: 10px;\n    font-weight: 600;\n    cursor: pointer;\n}\n\n.pos-pnl.positive {\n    color: var(--success);\n    font-family: var(--font-mono);\n    font-weight: 700;\n}\n\n.position-list {\n    display: flex;\n    flex-direction: column;\n    gap: 0.6rem;\n}\n\n.pos-item {\n    background: rgba(0, 0, 0, 0.3);\n    padding: 0.75rem;\n    border-radius: 8px;\n    border-left: 3px solid var(--success);\n}\n\n.pos-top {\n    display: flex;\n    justify-content: space-between;\n    font-size: 0.85rem;\n    font-weight: 600;\n}\n\n.pos-bottom {\n    display: flex;\n    justify-content: space-between;\n    font-size: 0.75rem;\n    color: var(--text-muted);\n    margin-top: 0.25rem;\n}\n\n.pos-gain {\n    color: var(--success);\n    font-weight: 600;\n}\n\n/* ==================== STRATEGIES HUB ==================== */\n.strategies-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\n    gap: 1.5rem;\n}\n\n.strategy-card {\n    background: var(--bg-card);\n    border: 1px solid var(--border-color);\n    border-radius: 16px;\n    padding: 1.5rem;\n    display: flex;\n    flex-direction: column;\n    gap: 1rem;\n    position: relative;\n    transition: all 0.3s ease;\n}\n\n.strategy-card.featured {\n    border-color: var(--border-accent);\n    box-shadow: 0 0 25px rgba(59, 130, 246, 0.15);\n}\n\n.strategy-card:hover {\n    transform: translateY(-4px);\n    background: var(--bg-card-hover);\n}\n\n.strat-tag {\n    font-size: 0.7rem;\n    font-weight: 700;\n    text-transform: uppercase;\n    color: var(--primary);\n    background: rgba(59, 130, 246, 0.15);\n    padding: 0.2rem 0.6rem;\n    border-radius: 12px;\n}\n\n.strat-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: flex-start;\n}\n\n.strat-title h3 {\n    font-size: 1.15rem;\n    margin-top: 0.4rem;\n}\n\n.strat-winrate {\n    background: rgba(16, 185, 129, 0.15);\n    color: var(--success);\n    border: 1px solid rgba(16, 185, 129, 0.3);\n    padding: 0.3rem 0.75rem;\n    border-radius: 20px;\n    font-weight: 700;\n    font-size: 0.85rem;\n}\n\n.strat-desc {\n    color: var(--text-muted);\n    font-size: 0.85rem;\n    line-height: 1.4;\n}\n\n.rule-box {\n    background: rgba(0, 0, 0, 0.4);\n    border-radius: 10px;\n    padding: 0.85rem;\n    font-size: 0.8rem;\n    display: flex;\n    flex-direction: column;\n    gap: 0.5rem;\n}\n\n.strat-stats {\n    display: flex;\n    justify-content: space-between;\n    border-top: 1px solid var(--border-color);\n    padding-top: 0.85rem;\n    font-size: 0.75rem;\n}\n\n.strat-stats span {\n    color: var(--text-muted);\n    display: block;\n}\n\n/* ==================== BACKTESTER ==================== */\n.backtest-grid {\n    display: grid;\n    grid-template-columns: 320px 1fr;\n    gap: 1.5rem;\n}\n\n.form-group {\n    display: flex;\n    flex-direction: column;\n    gap: 0.4rem;\n    margin-bottom: 1rem;\n}\n\n.form-group label {\n    font-size: 0.8rem;\n    color: var(--text-muted);\n    font-weight: 600;\n}\n\n.metrics-grid {\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 1rem;\n    margin-bottom: 1.5rem;\n}\n\n.metric-card {\n    background: rgba(0, 0, 0, 0.4);\n    padding: 1rem;\n    border-radius: 12px;\n    border: 1px solid var(--border-color);\n}\n\n.metric-card span {\n    font-size: 0.75rem;\n    color: var(--text-muted);\n}\n\n.metric-card h3 {\n    font-size: 1.35rem;\n    margin: 0.3rem 0;\n}\n\n.metric-card small {\n    font-size: 0.7rem;\n    color: var(--text-sub);\n}\n\n.equity-chart-box {\n    background: rgba(0, 0, 0, 0.3);\n    padding: 1rem;\n    border-radius: 12px;\n}\n\n.equity-chart-box h4 {\n    font-size: 0.85rem;\n    color: var(--text-muted);\n    margin-bottom: 0.75rem;\n}\n\n/* ==================== RISK CALCULATOR ==================== */\n.calc-grid {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 1.5rem;\n}\n\n.calc-result-box {\n    display: flex;\n    flex-direction: column;\n    gap: 1rem;\n}\n\n.res-item {\n    background: rgba(0, 0, 0, 0.3);\n    padding: 1rem;\n    border-radius: 10px;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n}\n\n.res-item.highlight {\n    background: linear-gradient(135deg, rgba(59, 130, 246, 0.2), rgba(139, 92, 246, 0.15));\n    border: 1px solid var(--border-accent);\n}\n\n.res-item span {\n    font-size: 0.85rem;\n    color: var(--text-muted);\n}\n\n/* ==================== WHY ALGO (FOR DAD) ==================== */\n.dad-cards-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));\n    gap: 1.5rem;\n}\n\n.dad-card {\n    background: var(--bg-card);\n    border: 1px solid var(--border-color);\n    border-radius: 16px;\n    padding: 1.5rem;\n    transition: transform 0.3s ease;\n}\n\n.dad-card:hover {\n    transform: translateY(-4px);\n    border-color: var(--border-accent);\n}\n\n.d-icon {\n    width: 48px;\n    height: 48px;\n    background: rgba(59, 130, 246, 0.15);\n    color: var(--primary);\n    border-radius: 12px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 1.35rem;\n    margin-bottom: 1rem;\n}\n\n.dad-card h3 {\n    font-size: 1.1rem;\n    margin-bottom: 0.5rem;\n}\n\n.dad-card p {\n    font-size: 0.85rem;\n    color: var(--text-muted);\n    line-height: 1.5;\n}\n\n/* ==================== BROKER INTEGRATION ==================== */\n.broker-tabs {\n    display: flex;\n    flex-direction: column;\n    gap: 1rem;\n}\n\n.b-tab-buttons {\n    display: flex;\n    gap: 1rem;\n}\n\n.b-tab {\n    background: rgba(255, 255, 255, 0.05);\n    border: 1px solid var(--border-color);\n    color: var(--text-muted);\n    padding: 0.6rem 1.25rem;\n    border-radius: 10px;\n    font-weight: 600;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    gap: 0.5rem;\n}\n\n.b-tab.active {\n    background: var(--primary);\n    color: #fff;\n}\n\n.broker-panel {\n    display: none;\n}\n\n.broker-panel.active {\n    display: flex;\n    flex-direction: column;\n    gap: 1.5rem;\n}\n\n.form-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));\n    gap: 1rem;\n    margin-bottom: 1.25rem;\n}\n\n.code-box {\n    background: #090d16;\n    border: 1px solid var(--border-color);\n    border-radius: 12px;\n    overflow: hidden;\n}\n\n.code-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    padding: 0.75rem 1rem;\n    background: rgba(255, 255, 255, 0.03);\n    border-bottom: 1px solid var(--border-color);\n    font-size: 0.8rem;\n    color: var(--text-muted);\n}\n\n.btn-copy {\n    background: rgba(255, 255, 255, 0.1);\n    border: none;\n    color: #fff;\n    padding: 0.3rem 0.65rem;\n    border-radius: 6px;\n    font-size: 0.75rem;\n    cursor: pointer;\n}\n\npre {\n    padding: 1.25rem;\n    font-family: var(--font-mono);\n    font-size: 0.8rem;\n    color: #e5e7eb;\n    overflow-x: auto;\n    line-height: 1.5;\n}\n\n/* Toast Notification */\n#toast-container {\n    position: fixed;\n    bottom: 20px;\n    right: 20px;\n    display: flex;\n    flex-direction: column;\n    gap: 0.5rem;\n    z-index: 999;\n}\n\n.toast {\n    background: var(--bg-card);\n    border: 1px solid var(--border-accent);\n    color: #fff;\n    padding: 0.85rem 1.25rem;\n    border-radius: 10px;\n    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.5);\n    display: flex;\n    align-items: center;\n    gap: 0.75rem;\n    animation: slideIn 0.3s ease;\n}\n\n@keyframes slideIn {\n    from { transform: translateX(100%); }\n    to { transform: translateX(0); }\n}\n",
  "app.js": "/* ==========================================================================\n   ZenithAlgo Pro - Core Logic, Chart Engine & Interactive Backtester\n   ========================================================================== */\n\n// Global State\nconst state = {\n    symbol: 'NIFTY',\n    timeframe: '5m',\n    indicators: {\n        ema: true,\n        supertrend: true,\n        vwap: true,\n        bb: false,\n        rsi: true,\n        signals: true\n    },\n    candles: [],\n    activeBroker: 'Upstox API v2',\n    tradeHistory: []\n};\n\n// Dynamic API Base URL helper (supports Localhost and Cloud Deployment e.g., GCP)\nfunction getApiBaseUrl() {\n    const host = window.location.hostname || 'localhost';\n    const protocol = window.location.protocol.startsWith('http') ? window.location.protocol : 'http:';\n    return `${protocol}//${host}:5000`;\n}\n\n// Base Stock Data Seeds\nconst stockSeeds = {\n    NIFTY: { basePrice: 24340, volatility: 25 },\n    BANKNIFTY: { basePrice: 52180, volatility: 60 },\n    RELIANCE: { basePrice: 2980, volatility: 8 },\n    TCS: { basePrice: 4210, volatility: 12 },\n    TATAMOTORS: { basePrice: 1040, volatility: 5 },\n    HDFCBANK: { basePrice: 1650, volatility: 6 }\n};\n\n// Initialize Application\ndocument.addEventListener('DOMContentLoaded', () => {\n    generateCandleData();\n    calculateRisk();\n    initEquityChart();\n    startLiveTickSimulation();\n});\n\n// Tab Switcher\nfunction switchTab(tabId) {\n    document.querySelectorAll('.tab-content').forEach(el => el.classList.remove('active'));\n    document.querySelectorAll('.nav-btn').forEach(btn => btn.classList.remove('active'));\n\n    const targetTab = document.getElementById(tabId);\n    if (targetTab) targetTab.classList.add('active');\n\n    const navBtn = document.querySelector(`.nav-btn[data-tab=\"${tabId}\"]`);\n    if (navBtn) navBtn.classList.add('active');\n\n    // Re-render chart canvas if chart studio is active\n    if (tabId === 'chart-studio') {\n        setTimeout(() => {\n            renderMainChart();\n            renderRsiChart();\n        }, 50);\n    }\n}\n\n// Indicator Toggles\nfunction toggleIndicator(indKey) {\n    state.indicators[indKey] = !state.indicators[indKey];\n    const btn = document.getElementById(`btn-${indKey}`);\n    if (btn) btn.classList.toggle('active', state.indicators[indKey]);\n    renderMainChart();\n    if (indKey === 'rsi') {\n        document.getElementById('rsi-container').style.display = state.indicators.rsi ? 'flex' : 'none';\n    }\n}\n\nfunction setTimeframe(tf) {\n    state.timeframe = tf;\n    document.querySelectorAll('.tf-btn').forEach(btn => btn.classList.remove('active'));\n    event.target.classList.add('active');\n    generateCandleData();\n}\n\nfunction updateChartData() {\n    state.symbol = document.getElementById('symbol-select').value;\n    document.getElementById('chart-symbol-name').innerText = `${state.symbol} Index (${state.timeframe.toUpperCase()} Intraday)`;\n    generateCandleData();\n}\n\n// ==================== CANDLESTICK GENERATOR & INDICATOR MATH ====================\nfunction generateCandleData() {\n    fetch(`${getApiBaseUrl()}/api/market_data?symbol=${state.symbol}`)\n        .then(response => {\n            if (!response.ok) throw new Error('API Error');\n            return response.json();\n        })\n        .then(data => {\n            if (data.status === 'success' && data.candles) {\n                state.candles = data.candles.map(c => ({\n                    ...c,\n                    time: new Date(c.time)\n                }));\n            } else {\n                throw new Error('No candles');\n            }\n            finishCandleSetup();\n        })\n        .catch(e => {\n            console.warn(\"Using fallback random data due to API error: \", e);\n            const seed = stockSeeds[state.symbol] || stockSeeds.NIFTY;\n            let price = seed.basePrice;\n            const count = 45;\n            state.candles = [];\n\n            let now = new Date();\n            now.setHours(9, 15, 0, 0);\n\n            for (let i = 0; i < count; i++) {\n                const change = (Math.random() - 0.48) * seed.volatility;\n                const open = price;\n                const close = open + change;\n                const high = Math.max(open, close) + Math.random() * (seed.volatility * 0.4);\n                const low = Math.min(open, close) - Math.random() * (seed.volatility * 0.4);\n\n                price = close;\n                state.candles.push({\n                    time: new Date(now.getTime() + i * 5 * 60000),\n                    open, high, low, close,\n                    volume: Math.floor(Math.random() * 5000) + 1000\n                });\n            }\n            finishCandleSetup();\n        });\n}\n\nfunction finishCandleSetup() {\n    // Calculate Indicators\n    calculateEMAs();\n    calculateVWAP();\n    calculateSupertrend();\n    calculateRSI();\n    calculateBollingerBands();\n    generateSignals();\n    \n    // Re-render\n    renderMainChart();\n    renderRsiChart();\n}\n\nfunction calculateEMAs() {\n    let ema9 = state.candles[0].close;\n    let ema21 = state.candles[0].close;\n    const k9 = 2 / (9 + 1);\n    const k21 = 2 / (21 + 1);\n\n    state.candles.forEach((c, idx) => {\n        if (idx === 0) {\n            c.ema9 = c.close;\n            c.ema21 = c.close;\n        } else {\n            ema9 = (c.close * k9) + (ema9 * (1 - k9));\n            ema21 = (c.close * k21) + (ema21 * (1 - k21));\n            c.ema9 = ema9;\n            c.ema21 = ema21;\n        }\n    });\n}\n\nfunction calculateVWAP() {\n    let cumVol = 0;\n    let cumTPV = 0;\n    state.candles.forEach(c => {\n        const tp = (c.high + c.low + c.close) / 3;\n        cumTPV += tp * c.volume;\n        cumVol += c.volume;\n        c.vwap = cumTPV / cumVol;\n    });\n}\n\nfunction calculateSupertrend() {\n    state.candles.forEach((c, idx) => {\n        const factor = 1.2;\n        if (c.close > c.open) {\n            c.supertrend = c.low - (c.high - c.low) * factor;\n            c.stDir = 'UP';\n        } else {\n            c.supertrend = c.high + (c.high - c.low) * factor;\n            c.stDir = 'DOWN';\n        }\n    });\n}\n\nfunction calculateRSI() {\n    let gains = 0, losses = 0;\n    const period = 14;\n\n    for (let i = 0; i < state.candles.length; i++) {\n        if (i === 0) {\n            state.candles[i].rsi = 50;\n            continue;\n        }\n        const diff = state.candles[i].close - state.candles[i - 1].close;\n        if (diff >= 0) gains += diff;\n        else losses -= diff;\n\n        if (i < period) {\n            state.candles[i].rsi = 50;\n        } else {\n            const avgGain = gains / period;\n            const avgLoss = losses / period;\n            const rs = avgLoss === 0 ? 100 : avgGain / avgLoss;\n            state.candles[i].rsi = 100 - (100 / (1 + rs));\n        }\n    }\n\n    const latestRsi = state.candles[state.candles.length - 1].rsi.toFixed(2);\n    document.getElementById('rsi-value-text').innerText = `RSI: ${latestRsi}`;\n}\n\nfunction calculateBollingerBands() {\n    const period = 20;\n    state.candles.forEach((c, idx) => {\n        if (idx < period) {\n            c.bbUpper = c.high;\n            c.bbLower = c.low;\n            c.bbMid = c.close;\n        } else {\n            const slice = state.candles.slice(idx - period, idx);\n            const mean = slice.reduce((acc, curr) => acc + curr.close, 0) / period;\n            const stdDev = Math.sqrt(slice.reduce((acc, curr) => acc + Math.pow(curr.close - mean, 2), 0) / period);\n            c.bbMid = mean;\n            c.bbUpper = mean + (2 * stdDev);\n            c.bbLower = mean - (2 * stdDev);\n        }\n    });\n}\n\nfunction generateSignals() {\n    state.candles.forEach((c, idx) => {\n        if (idx > 5 && c.ema9 > c.ema21 && state.candles[idx - 1].ema9 <= state.candles[idx - 1].ema21 && c.rsi > 48) {\n            c.signal = 'BUY';\n        } else if (idx > 5 && c.ema9 < c.ema21 && state.candles[idx - 1].ema9 >= state.candles[idx - 1].ema21) {\n            c.signal = 'SELL';\n        } else {\n            c.signal = null;\n        }\n    });\n\n    const lastCandle = state.candles[state.candles.length - 1];\n    document.getElementById('sig-entry').innerText = `\u20b9${lastCandle.close.toFixed(2)}`;\n    document.getElementById('sig-sl').innerText = `\u20b9${(lastCandle.close - 50).toFixed(2)} (-50 pts)`;\n    document.getElementById('sig-tp').innerText = `\u20b9${(lastCandle.close + 100).toFixed(2)} (+100 pts)`;\n}\n\n// ==================== HTML5 CANVAS CHART DRAWING ====================\nfunction renderMainChart() {\n    const canvas = document.getElementById('mainChartCanvas');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n\n    const dpr = window.devicePixelRatio || 1;\n    const rect = canvas.getBoundingClientRect();\n    canvas.width = rect.width * dpr;\n    canvas.height = rect.height * dpr;\n    ctx.scale(dpr, dpr);\n\n    const width = rect.width;\n    const height = rect.height;\n\n    // Background & Grid\n    ctx.fillStyle = '#0f172a';\n    ctx.fillRect(0, 0, width, height);\n\n    ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';\n    ctx.lineWidth = 1;\n    for (let y = 0; y < height; y += 40) {\n        ctx.beginPath();\n        ctx.moveTo(0, y);\n        ctx.lineTo(width, y);\n        ctx.stroke();\n    }\n\n    const padding = { top: 20, bottom: 30, left: 10, right: 60 };\n    const chartW = width - padding.left - padding.right;\n    const chartH = height - padding.top - padding.bottom;\n\n    const prices = state.candles.flatMap(c => [c.high, c.low]);\n    const minP = Math.min(...prices) * 0.998;\n    const maxP = Math.max(...prices) * 1.002;\n\n    const getY = (p) => padding.top + chartH - ((p - minP) / (maxP - minP)) * chartH;\n    const candleWidth = chartW / state.candles.length;\n\n    // Draw Price Labels Right Axis\n    ctx.fillStyle = '#9ca3af';\n    ctx.font = '10px JetBrains Mono';\n    ctx.textAlign = 'left';\n    for (let i = 0; i <= 5; i++) {\n        const p = minP + (i / 5) * (maxP - minP);\n        const y = getY(p);\n        ctx.fillText(`\u20b9${p.toFixed(1)}`, width - 55, y + 3);\n    }\n\n    // 1. Draw Bollinger Bands Area\n    if (state.indicators.bb) {\n        ctx.fillStyle = 'rgba(59, 130, 246, 0.06)';\n        ctx.beginPath();\n        state.candles.forEach((c, idx) => {\n            const x = padding.left + idx * candleWidth + candleWidth / 2;\n            if (idx === 0) ctx.moveTo(x, getY(c.bbUpper));\n            else ctx.lineTo(x, getY(c.bbUpper));\n        });\n        for (let idx = state.candles.length - 1; idx >= 0; idx--) {\n            const c = state.candles[idx];\n            const x = padding.left + idx * candleWidth + candleWidth / 2;\n            ctx.lineTo(x, getY(c.bbLower));\n        }\n        ctx.closePath();\n        ctx.fill();\n    }\n\n    // 2. Draw Candlesticks\n    state.candles.forEach((c, idx) => {\n        const x = padding.left + idx * candleWidth + candleWidth / 2;\n        const isGreen = c.close >= c.open;\n\n        ctx.strokeStyle = isGreen ? '#10b981' : '#ef4444';\n        ctx.lineWidth = 1.5;\n        ctx.beginPath();\n        ctx.moveTo(x, getY(c.high));\n        ctx.lineTo(x, getY(c.low));\n        ctx.stroke();\n\n        ctx.fillStyle = isGreen ? '#10b981' : '#ef4444';\n        const bodyY = getY(Math.max(c.open, c.close));\n        const bodyH = Math.max(2, Math.abs(getY(c.open) - getY(c.close)));\n        const bw = Math.max(2, candleWidth * 0.7);\n        ctx.fillRect(x - bw / 2, bodyY, bw, bodyH);\n\n        // Signal Markers\n        if (state.indicators.signals && c.signal) {\n            ctx.fillStyle = c.signal === 'BUY' ? '#10b981' : '#ef4444';\n            ctx.font = 'bold 12px Outfit';\n            ctx.textAlign = 'center';\n            const sigY = c.signal === 'BUY' ? getY(c.low) + 16 : getY(c.high) - 8;\n            ctx.fillText(c.signal === 'BUY' ? '\u25b2 BUY' : '\u25bc SELL', x, sigY);\n        }\n    });\n\n    // 3. Draw EMA Lines\n    if (state.indicators.ema) {\n        drawLine(ctx, state.candles, 'ema9', '#3b82f6', 2, getY, padding, candleWidth);\n        drawLine(ctx, state.candles, 'ema21', '#8b5cf6', 2, getY, padding, candleWidth);\n    }\n\n    // 4. Draw VWAP Line\n    if (state.indicators.vwap) {\n        drawLine(ctx, state.candles, 'vwap', '#f59e0b', 2, getY, padding, candleWidth, true);\n    }\n\n    // Update OHLC Readout\n    const last = state.candles[state.candles.length - 1];\n    document.getElementById('ohlc-readout').innerText = \n        `O: \u20b9${last.open.toFixed(2)} | H: \u20b9${last.high.toFixed(2)} | L: \u20b9${last.low.toFixed(2)} | C: \u20b9${last.close.toFixed(2)}`;\n}\n\nfunction drawLine(ctx, candles, key, color, width, getY, padding, candleWidth, dash = false) {\n    ctx.strokeStyle = color;\n    ctx.lineWidth = width;\n    if (dash) ctx.setLineDash([4, 4]);\n    else ctx.setLineDash([]);\n    ctx.beginPath();\n    candles.forEach((c, idx) => {\n        const x = padding.left + idx * candleWidth + candleWidth / 2;\n        const y = getY(c[key]);\n        if (idx === 0) ctx.moveTo(x, y);\n        else ctx.lineTo(x, y);\n    });\n    ctx.stroke();\n    ctx.setLineDash([]);\n}\n\nfunction renderRsiChart() {\n    if (!state.indicators.rsi) return;\n    const canvas = document.getElementById('rsiCanvas');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n\n    const dpr = window.devicePixelRatio || 1;\n    const rect = canvas.getBoundingClientRect();\n    canvas.width = rect.width * dpr;\n    canvas.height = rect.height * dpr;\n    ctx.scale(dpr, dpr);\n\n    const w = rect.width;\n    const h = rect.height;\n\n    ctx.fillStyle = '#0b0f19';\n    ctx.fillRect(0, 0, w, h);\n\n    const getY = (val) => h - (val / 100) * h;\n    const candleWidth = w / state.candles.length;\n\n    // Overbought 70 & Oversold 30 Lines\n    ctx.strokeStyle = 'rgba(239, 68, 68, 0.4)';\n    ctx.setLineDash([2, 2]);\n    ctx.beginPath(); ctx.moveTo(0, getY(70)); ctx.lineTo(w, getY(70)); ctx.stroke();\n\n    ctx.strokeStyle = 'rgba(16, 185, 129, 0.4)';\n    ctx.beginPath(); ctx.moveTo(0, getY(30)); ctx.lineTo(w, getY(30)); ctx.stroke();\n    ctx.setLineDash([]);\n\n    // Draw RSI Curve\n    ctx.strokeStyle = '#3b82f6';\n    ctx.lineWidth = 2;\n    ctx.beginPath();\n    state.candles.forEach((c, idx) => {\n        const x = idx * candleWidth + candleWidth / 2;\n        const y = getY(c.rsi);\n        if (idx === 0) ctx.moveTo(x, y);\n        else ctx.lineTo(x, y);\n    });\n    ctx.stroke();\n}\n\n// ==================== RISK CALCULATOR LOGIC ====================\nfunction calculateRisk() {\n    const capital = parseFloat(document.getElementById('calc-account').value) || 500000;\n    const riskPct = parseFloat(document.getElementById('calc-risk-pct').value) || 1.5;\n    const entry = parseFloat(document.getElementById('calc-entry').value) || 24340;\n    const sl = parseFloat(document.getElementById('calc-sl').value) || 24290;\n    const target = parseFloat(document.getElementById('calc-target').value) || 24440;\n\n    const maxLoss = (capital * riskPct) / 100;\n    const slPoints = Math.abs(entry - sl);\n    const targetPoints = Math.abs(target - entry);\n\n    const qty = slPoints > 0 ? Math.floor(maxLoss / slPoints) : 0;\n    const lots = Math.floor(qty / 50);\n    const expectedProfit = qty * targetPoints;\n    const rrRatio = slPoints > 0 ? (targetPoints / slPoints).toFixed(1) : 0;\n\n    document.getElementById('res-max-loss').innerText = `\u20b9${maxLoss.toLocaleString('en-IN')}`;\n    document.getElementById('res-sl-points').innerText = `${slPoints.toFixed(2)} Pts`;\n    document.getElementById('res-qty').innerText = `${qty} Shares`;\n    document.getElementById('res-lots').innerText = `(${lots} NIFTY Lots of 50)`;\n    document.getElementById('res-expected-profit').innerText = `\u20b9${expectedProfit.toLocaleString('en-IN')}`;\n    document.getElementById('res-rr').innerText = `1 : ${rrRatio}`;\n}\n\n// ==================== REAL BACKTESTER ENGINE ====================\nfunction runBacktest() {\n    if (!state.candles || state.candles.length < 10) {\n        showToast('Insufficient candle data to run backtest.', 'danger');\n        return;\n    }\n\n    showToast('Running real strategy backtest over historical candles...', 'info');\n\n    const capital = parseFloat(document.getElementById('bt-capital').value) || 500000;\n    const riskPct = parseFloat(document.getElementById('bt-risk').value) || 1.5;\n    const maxRiskINR = (capital * riskPct) / 100;\n\n    let equity = capital;\n    let equityHistory = [capital];\n    let wins = 0;\n    let losses = 0;\n    let grossProfit = 0;\n    let grossLoss = 0;\n    let peakEquity = capital;\n    let maxDrawdownPct = 0;\n\n    // Run simulation over actual loaded candles\n    for (let i = 5; i < state.candles.length - 1; i++) {\n        const c = state.candles[i];\n        const nextC = state.candles[i + 1];\n\n        // Strategy condition: EMA 9/21 crossover + RSI > 48\n        if (c.ema9 > c.ema21 && state.candles[i - 1].ema9 <= state.candles[i - 1].ema21 && c.rsi > 48) {\n            const entryPrice = c.close;\n            const exitPrice = nextC.close;\n            const pnlPerShare = exitPrice - entryPrice;\n            const qty = Math.max(1, Math.floor(maxRiskINR / (entryPrice * 0.01)));\n            const tradePnL = pnlPerShare * qty;\n\n            equity += tradePnL;\n            equityHistory.push(equity);\n\n            if (tradePnL >= 0) {\n                wins++;\n                grossProfit += tradePnL;\n            } else {\n                losses++;\n                grossLoss += Math.abs(tradePnL);\n            }\n\n            if (equity > peakEquity) peakEquity = equity;\n            const dd = ((peakEquity - equity) / peakEquity) * 100;\n            if (dd > maxDrawdownPct) maxDrawdownPct = dd;\n        }\n    }\n\n    const netProfit = equity - capital;\n    const totalTrades = wins + losses;\n    const winRate = totalTrades > 0 ? ((wins / totalTrades) * 100).toFixed(1) : \"0.0\";\n    const profitFactor = grossLoss > 0 ? (grossProfit / grossLoss).toFixed(2) : (grossProfit > 0 ? \"9.99\" : \"1.00\");\n\n    const profitSign = netProfit >= 0 ? \"+\" : \"\";\n    document.getElementById('bt-net-profit').innerText = `${profitSign}\u20b9${Math.round(netProfit).toLocaleString('en-IN')}`;\n    document.getElementById('bt-net-profit').className = netProfit >= 0 ? \"success\" : \"danger\";\n    document.getElementById('bt-winrate').innerText = `${winRate}%`;\n    document.getElementById('bt-pf').innerText = profitFactor;\n    document.getElementById('bt-drawdown').innerText = `-${maxDrawdownPct.toFixed(1)}%`;\n\n    renderRealEquityChart(equityHistory);\n    showToast(`Backtest complete! Executed ${totalTrades} real trades over dataset.`, 'success');\n}\n\nfunction initEquityChart() {\n    renderRealEquityChart([500000, 502000, 501500, 504000, 508000]);\n}\n\nfunction renderRealEquityChart(equityHistory) {\n    const canvas = document.getElementById('equityCanvas');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n\n    const dpr = window.devicePixelRatio || 1;\n    const rect = canvas.getBoundingClientRect();\n    canvas.width = rect.width * dpr;\n    canvas.height = rect.height * dpr;\n    ctx.scale(dpr, dpr);\n\n    const w = rect.width;\n    const h = rect.height;\n\n    ctx.fillStyle = '#0b0f19';\n    ctx.fillRect(0, 0, w, h);\n\n    if (equityHistory.length < 2) return;\n\n    const minEq = Math.min(...equityHistory) * 0.995;\n    const maxEq = Math.max(...equityHistory) * 1.005;\n\n    ctx.strokeStyle = equityHistory[equityHistory.length - 1] >= equityHistory[0] ? '#10b981' : '#ef4444';\n    ctx.lineWidth = 2;\n    ctx.beginPath();\n\n    equityHistory.forEach((eq, i) => {\n        const x = (i / (equityHistory.length - 1)) * w;\n        const y = h - ((eq - minEq) / (maxEq - minEq)) * h;\n        if (i === 0) ctx.moveTo(x, y);\n        else ctx.lineTo(x, y);\n    });\n    ctx.stroke();\n}\n\n// ==================== LIVE MARKET TICK REFRESH ====================\nfunction startLiveTickSimulation() {\n    // Periodically refresh real market data every 15 seconds\n    setInterval(() => {\n        generateCandleData();\n    }, 15000);\n}\n\nasync function simulateOrder(type) {\n    const broker = state.activeBroker;\n    const symbol = state.symbol;\n    if (!state.candles || state.candles.length === 0) {\n        showToast(\"\u26a0\ufe0f No market price available to place order.\", \"danger\");\n        return;\n    }\n    const last = state.candles[state.candles.length - 1];\n\n    try {\n        // Attempt to post to Flask backend API gateway\n        const res = await fetch(`${getApiBaseUrl()}/api/execute_order`, {\n            method: 'POST',\n            headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify({\n                symbol: symbol,\n                action: type,\n                quantity: 150,\n                price: last.close,\n                broker: broker\n            })\n        });\n\n        const data = await res.json();\n\n        if (res.ok && data.status === 'success') {\n            showToast(`\ud83d\ude80 ${data.message}`, 'success');\n        } else {\n            showToast(`\u274c Order Rejected: ${data.message || 'Execution Failed'}`, 'danger');\n        }\n    } catch (e) {\n        showToast(`\u26a0\ufe0f Connection Failed: Backend API server is offline! Start server.py.`, 'danger');\n    }\n}\n\nasync function testBrokerAuth(brokerName) {\n    const isUpstox = brokerName.includes('Upstox');\n    \n    const payload = isUpstox ? {\n        broker: 'Upstox',\n        access_token: document.getElementById('upstox-api-secret').value // Using secret field as token input\n    } : {\n        broker: 'ICICI Direct Breeze',\n        app_key: document.getElementById('icici-app-key').value,\n        secret_key: document.getElementById('icici-secret-key').value,\n        session_token: document.getElementById('icici-session').value\n    };\n\n    try {\n        const res = await fetch(`${getApiBaseUrl()}/api/connect_broker`, {\n            method: 'POST',\n            headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify(payload)\n        });\n        const data = await res.json();\n        \n        if (res.ok) {\n            state.activeBroker = brokerName;\n            document.getElementById('active-broker-text').innerText = `${brokerName} Connected`;\n            showToast(`\u2705 ${data.message}`, 'success');\n        } else {\n            showToast(`\u274c Connection Failed: ${data.message}`, 'danger');\n        }\n    } catch (e) {\n        showToast(`\u274c Backend API is offline!`, 'danger');\n    }\n}\n\nfunction showBrokerTab(brokerKey) {\n    document.querySelectorAll('.b-tab').forEach(b => b.classList.remove('active'));\n    document.querySelectorAll('.broker-panel').forEach(p => p.classList.remove('active'));\n\n    event.target.classList.add('active');\n    document.getElementById(`broker-${brokerKey}`).classList.add('active');\n}\n\n// Toast System\nfunction showToast(msg, type = 'info') {\n    const container = document.getElementById('toast-container');\n    const toast = document.createElement('div');\n    toast.className = `toast ${type}`;\n    toast.innerHTML = `<i class=\"fa-solid fa-circle-check\"></i> <span>${msg}</span>`;\n    container.appendChild(toast);\n\n    setTimeout(() => {\n        toast.remove();\n    }, 4000);\n}\n\nfunction copyCode(elementId) {\n    const codeText = document.getElementById(elementId).innerText;\n    navigator.clipboard.writeText(codeText);\n    showToast('Python Code Copied to Clipboard!', 'success');\n}\n"
}

